16	fn run_invalid_manifests(input: &'static str, _: &str, _: &str, _: &str) {
17	    let input_file = Utf8Path::new(input);
18	    let file_name = input_file.file_name().unwrap();
19	    let input_code = read_to_string(input_file)
20	        .unwrap_or_else(|err| panic!("failed to read {input_file:?}: {err:?}"));
21	
22	    let mut package = NodeJsPackage::default();
23	    match input_file.extension().map(str::as_bytes) {
24	        Some(b"json") => {
25	            let parsed = parse_json(input_code.as_str(), JsonParserOptions::default());
26	            package.insert_serialized_manifest(&parsed.tree(), input_file);
27	        }
28	        _ => {
29	            panic!("Extension not supported");
30	        }
31	    };
32	
33	    let result = package.analyze();
34	
35	    assert!(
36	        package.has_errors() || !result.diagnostics.is_empty(),
37	        "The file {input} should have diagnostics, but it doesn't have any"
38	    );
39	
40	    let mut diagnostics_string = package
41	        .diagnostics
42	        .into_iter()
43	        .map(|diagnostic| {
44	            print_diagnostic_to_string(
45	                &diagnostic
46	                    .with_file_path(file_name)
47	                    .with_file_source_code(input_code.as_str()),
48	            )
49	        })
50	        .collect::<Vec<_>>()
51	        .join("\n\n");
52	
53	    for diagnostic in result.diagnostics {
54	        diagnostics_string.push_str(&print_diagnostic_to_string(
55	            &diagnostic
56	                .with_file_path(file_name)
57	                .with_file_source_code(input_code.as_str()),
58	        ));
59	        diagnostics_string.push_str("\n\n");
60	    }
61	
62	    insta::with_settings!({
63	        prepend_module_to_snapshot => false,
64	        snapshot_path => input_file.parent().unwrap(),
65	    }, {
66	        insta::assert_snapshot!(file_name, diagnostics_string, file_name);
67	    });
68	}
