+impl biome_console::fmt::Display for UnsupportedRuleDisplay<'_> {
+    fn fmt(&self, fmt: &mut biome_console::fmt::Formatter) -> std::io::Result<()> {
+        fmt.write_markup(markup! { {self.rule}" - "<Dim>{self.reason}</Dim> })
+    }
+}
